pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {

        vm.prank(address(this));
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == c.owner());
        }
    }
}
